begin;
create table trade_business.file_assets(company_id uuid not null,id uuid not null,order_id uuid,category text not null check(category in ('customer','purchase','customs','document','signature','export')),name text not null,mime text not null check(mime in ('application/pdf','image/png','image/jpeg','text/csv','application/zip')),size integer not null check(size>0 and size<=62914560),sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),object_path text not null,state text not null default 'pending' check(state in ('pending','uploading','stored','needs_reconciliation')),created_by uuid not null,created_at timestamptz not null default now(),primary key(company_id,id),unique(company_id,order_id,id),unique(object_path),foreign key(company_id,order_id) references trade_business.orders(company_id,id),check((category='signature' and order_id is null and size<=2097152 and mime in ('image/png','image/jpeg')) or (category<>'signature' and order_id is not null and (category='export' or (size<=10485760 and mime in ('application/pdf','image/png','image/jpeg'))))));
create index files_order on trade_business.file_assets(company_id,order_id,category,state);
create table trade_business.upload_intents(company_id uuid not null,id uuid not null,file_id uuid not null,created_by uuid not null,created_at timestamptz not null default now(),primary key(company_id,id),unique(company_id,file_id),foreign key(company_id,file_id) references trade_business.file_assets(company_id,id));
create table trade_business.upload_parts(company_id uuid not null,file_id uuid not null,part integer not null check(part between 0 and 4),size integer not null check(size>0 and size<=2097152),sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),stored boolean not null default false,primary key(company_id,file_id,part),foreign key(company_id,file_id) references trade_business.upload_intents(company_id,file_id));
grant update(stored) on trade_business.upload_parts to business_backend;
grant select,insert on trade_business.upload_parts,trade_business.file_assets,trade_business.upload_intents to business_backend;
grant update(state) on trade_business.file_assets to business_backend;
commit;
